INSERT INTO reg_2020 (siren,raison_sociale,etat,nature_juridique,date_creation,naf,siret,commune)
SELECT siren,raison_sociale,etat,nature_juridique,NULLIF(date_creation,'')::date,naf,siret,commune
FROM json_populate_recordset(NULL::record, $j$[{"siren": "490885498", "raison_sociale": "LEARNING MANAGEMENT DEVELOPPEMENT", "etat": "A", "nature_juridique": "5710", "date_creation": "2006-06-23", "naf": "85.41Z", "siret": "49088549800116", "commune": "PARIS"}, {"siren": "880418033", "raison_sociale": "WORMSENSING", "etat": "A", "nature_juridique": "5710", "date_creation": "2020-01-03", "naf": "26.11Z", "siret": "88041803300036", "commune": "SEYSSINET-PARISET"}]$j$) AS (siren TEXT,raison_sociale TEXT,etat TEXT,nature_juridique TEXT,date_creation TEXT,naf TEXT,siret TEXT,commune TEXT);


-- ---------------------------------------------------------------------
-- Apply onto legal_entities (match by SIREN)
-- ---------------------------------------------------------------------
UPDATE legal_entities le SET
  legal_name = r.raison_sociale,
  siret = r.siret,
  naf_code = r.naf,
  incorporation_date = r.date_creation,
  registered_city = r.commune,
  legal_form = CASE r.nature_juridique
                 WHEN '5710' THEN 'SAS' WHEN '5785' THEN 'SAS'
                 WHEN '5599' THEN 'SA'  WHEN '5699' THEN 'SA'
                 WHEN '5499' THEN 'SARL'
                 WHEN '5308' THEN 'SCA'
                 WHEN '6540' THEN 'SCI'
                 ELSE r.nature_juridique END,
  verification_status = CASE WHEN r.etat='A' THEN 'verified' WHEN r.etat='C' THEN 'ceased' ELSE 'verified' END,
  updated_at = NOW()
FROM reg_2020 r
WHERE le.siren = r.siren;

-- ---------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------
SELECT 'legal_entities updated' AS entity, COUNT(*)::text AS count
FROM legal_entities le JOIN reg_2020 r ON r.siren=le.siren
UNION ALL SELECT 'verified (active)', COUNT(*)::text FROM legal_entities le JOIN reg_2020 r ON r.siren=le.siren WHERE le.verification_status='verified'
UNION ALL SELECT 'ceased', COUNT(*)::text FROM legal_entities le JOIN reg_2020 r ON r.siren=le.siren WHERE le.verification_status='ceased';

DROP TABLE IF EXISTS reg_2020;

COMMIT;
